# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: Reflex wrappers around the CodeMirror 6 editors: cell_editor.jsx (each notebook
#          cell) and sql_editor.jsx (a table view's mini SQL runner, render.table_sql).
# Usage: cell_editor(initial_code=..., complete_url=..., edit_url=..., token=..., on_run=...,
#        on_save=...) sql_editor(initial_sql=..., columns=..., keys=..., on_run=...)   a
#        table's SQL box sql_editor(initial_sql=..., schema=..., keys=..., edit_url=...,
#        on_run=..., on_save=...)   a SmashDb console
# ---------------------------------------------------------------------------
from __future__ import annotations

import reflex as rx
from reflex.event import no_args_event_spec, passthrough_event_spec

# shared=True: the .jsx lives next to this module and is linked into the frontend build.
_SOURCE = rx.asset("./cell_editor.jsx", shared=True)
# sql_editor.jsx imports the theme from cell_editor.jsx; both are linked into the same folder.
_SQL_SOURCE = rx.asset("./sql_editor.jsx", shared=True)
# Both import the Alt+I inline chat from it; linked into the same folder.
_INLINE_SOURCE = rx.asset("./inline_edit.jsx", shared=True)
# The inline chat's box, imported by inline_edit.jsx; the Terminal's page shows the same one
# (terminal.inline_box serves this file to it).
_INLINE_BOX_SOURCE = rx.asset("./inline_box.js", shared=True)
_INLINE_DEPENDENCIES = ["@codemirror/merge", "@codemirror/commands"]


class CellEditor(rx.NoSSRComponent):
    """Client-only: CodeMirror needs a real DOM."""

    library = "$/public/" + _SOURCE
    tag = "CellEditor"
    lib_dependencies: list[str] = [
        "@uiw/react-codemirror",
        "@uiw/codemirror-themes",
        "@codemirror/lang-python",
        "@codemirror/autocomplete",
        "@codemirror/view",
        "@codemirror/state",
        "@lezer/highlight",
        *_INLINE_DEPENDENCIES,
    ]

    # Text the editor starts with. Later edits stay in the browser until run or blur.
    initial_code: rx.Var[str]
    # Backend URL that returns completions, and the session to complete against.
    complete_url: rx.Var[str]
    token: rx.Var[str]
    # Backend URL for the Alt+I inline chat (api.py /inline_edit).
    edit_url: rx.Var[str]

    # The keymap, in CodeMirror's spelling: {"run", "runAndAdvance", "complete", "runAll", ...}
    # (shortcuts.codemirror_keys).
    keys: rx.Var[dict[str, str]]

    # (code, advance): Shortcut.RUN_AND_ADVANCE sends advance=True, Shortcut.RUN False.
    on_run: rx.EventHandler[passthrough_event_spec(str, bool)]
    # (code): fired when the editor loses focus (and
    # before on_run_all, so it runs what is typed).
    on_save: rx.EventHandler[passthrough_event_spec(str)]
    # The console's keys, from the cell the cursor is in: Shortcut.RUN_ALL, CLEAR_OUTPUTS,
    # CELL_BELOW (a new cell under this one), DELETE_CELL (this one).
    on_run_all: rx.EventHandler[no_args_event_spec]
    on_clear_outputs: rx.EventHandler[no_args_event_spec]
    on_add_below: rx.EventHandler[no_args_event_spec]
    on_delete: rx.EventHandler[no_args_event_spec]


cell_editor = CellEditor.create


class SqlEditor(rx.NoSSRComponent):
    """Client-only: CodeMirror needs a real DOM."""

    library = "$/public/" + _SQL_SOURCE
    tag = "SqlEditor"
    lib_dependencies: list[str] = [
        "@uiw/react-codemirror",
        "@uiw/codemirror-themes",
        "@codemirror/lang-sql",
        "@codemirror/autocomplete",
        "@codemirror/view",
        "@codemirror/state",
        "@lezer/highlight",
        *_INLINE_DEPENDENCIES,
    ]

    # The query the box starts with; it is remounted (key) per view slot.
    initial_sql: rx.Var[str]
    # The table's columns, completed after "self." and in the query.
    columns: rx.Var[list[str]]
    # Instead of columns, for a whole database (a SmashDb console): {table: its columns}.
    schema: rx.Var[dict[str, list[str]]]
    # Shown while the box is empty (default: "select * from self").
    placeholder: rx.Var[str]
    # {"run", "complete"} in CodeMirror's spelling (shortcuts.sql_keys).
    keys: rx.Var[dict[str, str]]
    # Backend URL for the Alt+I inline chat (api.py /inline_edit); without it the box has none.
    edit_url: rx.Var[str]
    # The session, so Alt+I can read its chat.
    token: rx.Var[str]

    # (sql): fired by Shortcut.RUN_SQL, with the selection
    # when there is one, else the whole text.
    on_run: rx.EventHandler[passthrough_event_spec(str)]
    # (text): the whole text, fired when the box loses focus and just before on_run. Optional.
    on_save: rx.EventHandler[passthrough_event_spec(str)]


sql_editor = SqlEditor.create
